/* Shot or Spill service worker. Generated by scripts/build-sw.ts — do not edit dist/sw.js by hand.
 *
 * Strategy:
 *  - Precache the whole app shell on install (it's small and fully static).
 *  - Navigations: serve the cached app shell (index.html) so the game opens
 *    offline. The app state lives in localStorage, so a saved night survives.
 *  - Same-origin GETs: cache-first, since every asset filename is hashed.
 *  - Never touch cross-origin or non-GET requests (and there are none: the
 *    CSP in vercel.json only allows 'self').
 */
const VERSION = "__SW_VERSION__";
const CACHE = "shot-or-spill-" + VERSION;
const PRECACHE = __PRECACHE_MANIFEST__;
const SHELL = "/index.html";

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(PRECACHE)).then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

// The page tells a waiting worker to take over now (the "Update" button).
self.addEventListener("message", (event) => {
  if (event.data === "skip-waiting") self.skipWaiting();
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // App navigations always resolve to the cached shell (offline-first SPA).
  if (request.mode === "navigate") {
    event.respondWith(
      caches.match(SHELL).then((cached) => cached || fetch(request)),
    );
    return;
  }

  // Hashed assets: cache-first, then fall back to the network and cache it.
  event.respondWith(
    caches.match(request).then((cached) => {
      if (cached) return cached;
      return fetch(request).then((response) => {
        if (response.ok && response.type === "basic") {
          const copy = response.clone();
          caches.open(CACHE).then((cache) => cache.put(request, copy));
        }
        return response;
      });
    }),
  );
});
